def transform(grid):
    h, w = len(grid), len(grid[0])

    def line(axis, k):
        return list(grid[k]) if axis == "row" else [grid[r][k] for r in range(h)]

    def has_pair(values):
        return any(values[i] != 0 and values[i] == values[j]
                   for i in range(len(values)) for j in range(i + 1, len(values)))

    row_count = sum(has_pair(line("row", r)) for r in range(h))
    col_count = sum(has_pair(line("col", c)) for c in range(w))
    axis = "row" if row_count > col_count else "col"
    n = w if axis == "row" else h
    out = [row[:] for row in grid]

    for k in range(h if axis == "row" else w):
        values = line(axis, k)
        candidates = set()
        for i in range(n):
            if values[i] == 0:
                continue
            for j in range(i + 1, n):
                if values[j] == values[i]:
                    p = j - i
                    candidates.add((p, i % p))

        for p, residue in sorted(candidates):
            marks = [(i, values[i]) for i in range(n)
                     if i % p == residue and values[i] != 0]
            counts = {}
            for _, color in marks:
                counts[color] = counts.get(color, 0) + 1
            paired = [color for color, count in counts.items() if count >= 2]
            singles = [color for color, count in counts.items() if count == 1]
            if not paired:
                continue

            bounded = len(paired) == 1 and len(singles) == 1
            color = singles[0] if bounded else paired[0]
            lo = min(i for i, _ in marks) if bounded else 0
            hi = max(i for i, _ in marks) if bounded else n - 1

            for i in range(lo, hi + 1):
                if i % p == residue:
                    if axis == "row":
                        out[k][i] = color
                    else:
                        out[i][k] = color

    return out
